<?php
session_start();require_once '../conexion.php';if(!isset($_SESSION['usuario_id'])||$_SESSION['rol']!=='admin'){header('Location: ../login.php');exit;}$id=trim($_GET['id']??'');$mensaje='Operario inválido.';if($id!==''){$stmt=$conexion->prepare("SELECT COUNT(*) total FROM Pedido WHERE ci_operario=?");$stmt->bind_param('s',$id);$stmt->execute();$n=(int)$stmt->get_result()->fetch_assoc()['total'];if($n>0)$mensaje='No se puede eliminar: el operario tiene pedidos asociados. Podés marcarlo Inactivo.';else{$conexion->begin_transaction();try{$stmt=$conexion->prepare("DELETE FROM Operario WHERE CI=?");$stmt->bind_param('s',$id);$stmt->execute();$stmt=$conexion->prepare("DELETE FROM Persona WHERE CI=? AND Rol='Operario'");$stmt->bind_param('s',$id);$stmt->execute();$conexion->commit();$mensaje='Operario eliminado correctamente.';}catch(Throwable $e){$conexion->rollback();$mensaje='No se pudo eliminar: '.$e->getMessage();}}}header('Location: operarios.php?mensaje='.urlencode($mensaje));exit;?>